// Which days may change, which give context, and which Docs to read. No AI.
const j = $input.first().json;
const rows = j.rows; // [{row_number, day, topic, group_a.., plan_url, plan_cell, original_cell, completed}]
const i = rows.findIndex(r => r.row_number === j.row_number);
const today = rows[i];
const blockFrom = s => { const out = []; for (let k = s; k < rows.length && rows[k].topic === rows[s].topic; k++) out.push(rows[k]); return out; };
let s = i; while (s > 0 && rows[s - 1].topic === today.topic) s--;
const topicRows = blockFrom(s);
const pos = topicRows.indexOf(today);
const nextStart = s + topicRows.length;
const nextTopic = nextStart < rows.length ? blockFrom(nextStart) : [];
const task = j.make_easier ? 'easier_day' : 'replan_topic';
let scope, next, lastDay = false;
if (task === 'easier_day') { scope = [today]; next = rows.slice(i + 1, i + 3); }
else if (pos < topicRows.length - 1) { scope = topicRows.slice(pos + 1); next = nextTopic.slice(0, 2); }
else { lastDay = true; scope = nextTopic.slice(0, 2); next = rows.slice(nextStart + 2, nextStart + 4); }
const history = topicRows.slice(0, pos + 1);
const docId = u => (String(u || '').match(/\/d\/([\w-]{20,})/) || [])[1] || null;
const short = r => ({ day: r.day, topic: r.topic, row_number: r.row_number });
const docs = [];
for (const r of [...new Set([...history, ...scope, ...next])]) {
  if (docId(r.plan_url)) docs.push({ day: r.day, which: 'plan', doc_id: docId(r.plan_url) });
  if (docId(r.original_cell)) docs.push({ day: r.day, which: 'original', doc_id: docId(r.original_cell) });
}
return [{ json: { ...j, task, last_day_of_topic: lastDay, today: short(today), history: history.map(short), scope: scope.map(short), next: next.map(short), docs } }];

// Step 0: everything the models need, from the Docs and the Curriculum data sheet. No AI.
const p = $('Pick days').first().json;
const read = $('Drive: read day Docs').all();
const docs = $('One item per Doc').all().map((it, k) => ({ ...it.json, text: String(read[k]?.json?.data || '') }));
const table = v => { const [h, ...r] = v.values || []; return r.map(x => Object.fromEntries(h.map((k, n) => [k, x[n] ?? '']))); };
const acts = Object.fromEntries(table($('Sheets: Activities').first().json).map(a => [a.activity_id, a]));
const levels = Object.fromEntries(table($('Sheets: Levels').first().json).map(l => [l.level_id, l]));
const G = ['A', 'B', 'C'];
// "Skill (NUM-04): ..." / "Activity (NUM-04-A2): ..." lines, in the order Group A, B, C.
const parse = t => {
  const ac = [...t.matchAll(/Activity \(([A-Z]{3}-\d{2}-A\d+)\)/g)].map(m => m[1]);
  if (ac.length < 3) return null;
  const line = re => ((t.match(re) || [])[1] || '').trim();
  const checks = [...t.matchAll(/^Check:\s*(.+)$/gm)].map(m => m[1].trim());
  return { groups: Object.fromEntries(G.map((g, n) => [g, { level_id: ac[n].slice(0, 6), activity_id: ac[n] }])),
    opening: line(/Whole class opening \(5 min\)\s*\r?\n(.+)/), rotation: line(/Rotation\s*\r?\n(.+)/),
    checks: Object.fromEntries(G.map((g, n) => [g, checks[n] || ''])) };
};
const dayInfo = {};
for (const r of [...p.history, ...p.scope, ...p.next]) {
  const t = w => (docs.find(d => d.day === r.day && d.which === w) || {}).text || '';
  dayInfo[r.day] = { ...r, ...(parse(t('plan')) || parse(t('original')) || { groups: null }) };
}
const title = id => (acts[id] || {}).title || '?';
const withTitles = d => d && d.groups ? { day: d.day, topic: d.topic, ...Object.fromEntries(G.map(g => ['group_' + g.toLowerCase(),
  { ...d.groups[g], activity_title: title(d.groups[g].activity_id) }])) } : { day: d.day, topic: d.topic, unreadable: true };
const fb = p.feedback;
const result = { A: fb.group_a_result, B: fb.group_b_result, C: fb.group_c_result };
const notDone = g => /^(partly|no)$/i.test(String(result[g] || ''));
const today = dayInfo[p.today.day];
const history = Object.fromEntries(G.map(g => [g, p.history.map(h => dayInfo[h.day].groups?.[g]?.activity_id).filter(Boolean)]));
// Candidates: same strand, each group's level (today and on the day) +/- 1. Group A oral/hands-on only.
const byStrandNo = (strand, no) => Object.values(levels).find(l => l.strand_id === strand && Number(l.level_no) === no);
const near = id => { const l = levels[id]; if (!l) return []; const n = Number(l.level_no);
  return [n - 1, n, n + 1].map(x => byStrandNo(l.strand_id, x)).filter(Boolean).map(x => x.level_id); };
const candidates = {};
for (const g of G) {
  const lv = new Set();
  for (const d of p.scope) {
    const base = dayInfo[d.day].groups?.[g]?.level_id;
    if (base) near(base).forEach(x => lv.add(x));
    const t = today.groups?.[g]?.level_id;
    if (t && base && t.slice(0, 3) === base.slice(0, 3)) near(t).forEach(x => lv.add(x));
  }
  candidates[g] = Object.values(acts).filter(a => lv.has(a.level_id))
    .filter(a => g !== 'A' || /^(oral|hands-on)$/i.test(a.mode))
    .filter(a => !(notDone(g) && a.activity_id === today.groups?.[g]?.activity_id))
    .map(a => { const k = history[g].indexOf(a.activity_id);
      return a.activity_id + ' | ' + a.level_id + ' | ' + a.title + ' | ' + a.mode + ' | ' + a.minutes + ' min' + (k < 0 ? '' : ' | done on Day ' + p.history[k].day); });
}
const usedLevels = [...new Set([...Object.values(candidates).flat().map(c => c.split(' | ')[1]),
  ...Object.values(dayInfo).flatMap(d => d.groups ? G.map(g => d.groups[g].level_id) : [])])].sort();
const pending = (fb.pending || []).map(x => (x.group ? 'Group ' + x.group + ': ' : '') + x.what);
return [{ json: {
  task: p.task, last_day_of_topic: p.last_day_of_topic, today: p.today, scope: p.scope, next: p.next,
  feedback: { day: fb.day_number, topic: fb.topic, completed: fb.completed, group_a: result.A, group_b: result.B, group_c: result.C,
    what_went_well: fb.what_went_well, what_went_wrong: fb.what_went_wrong, how_to_improve: fb.how_to_improve,
    what_is_left: fb.what_is_left, other_notes: fb.other_notes, pending },
  result, history, candidates,
  levels: Object.fromEntries(usedLevels.filter(id => levels[id]).map(id => [id, levels[id].can_statement])),
  reported_day: withTitles(today), scope_days: p.scope.map(d => withTitles(dayInfo[d.day])), next_days: p.next.map(d => withTitles(dayInfo[d.day])),
  day_info: dayInfo, acts, level_meta: Object.fromEntries(Object.values(levels).map(l => [l.level_id, { strand: l.strand_id, no: Number(l.level_no) }])),
  docs_read: docs.length, docs_unreadable: Object.values(dayInfo).filter(d => !d.groups).map(d => d.day),
} }];

const c = $json;
const prompt = [
  'Teacher feedback:', JSON.stringify(c.feedback, null, 1),
  '', 'What each group did on the reported day (Day ' + c.today.day + '):', JSON.stringify(c.reported_day, null, 1),
  '', 'Skills:', JSON.stringify(c.levels, null, 1),
  '', 'For each group A, B, C give: status (on_track, needs_repeat or ahead), pending (the unfinished work in one short line, or null), root_cause (why it went wrong in one short line, or null).',
  'Reply with JSON only: {"groups":[{"group":"A","status":"on_track","pending":null,"root_cause":null},{"group":"B",...},{"group":"C",...}]}',
].join('\n');
return [{ json: { prompt } }];

// Parse the diagnosis. If the model reply is unusable, derive it from the Yes/Partly/No answers.
const c = $('Gather context').first().json;
const parseOut = v => { if (v && typeof v === 'object' && !('text' in v)) return v; let t = String((v && v.text) || '').replace(/<think>[\s\S]*?<\/think>/g, ''); return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
let groups = null;
try { groups = parseOut($json).groups; } catch (e) {}
const ok = Array.isArray(groups) && ['A', 'B', 'C'].every(g => groups.some(x => x.group === g));
if (!ok) groups = ['A', 'B', 'C'].map(g => ({ group: g, status: /^(partly|no)$/i.test(c.result[g] || '') ? 'needs_repeat' : 'on_track',
  pending: (c.feedback.pending.find(x => x.startsWith('Group ' + g)) || null), root_cause: null }));
return [{ json: { diagnosis: groups.map(x => ({ group: x.group, status: x.status, pending: x.pending || null, root_cause: x.root_cause || null })), diagnosis_from_model: ok } }];

// Builds the Plan prompt. Comes here first from Diagnose, again after a failed rule check or a REVISE from the challenger.
const c = $('Gather context').first().json;
const diagnosis = $('Read diagnosis').first().json.diagnosis;
const st = $json.state || { plan_calls: 0, fails: 0, challenge_round: 0 };
const allowed = c.scope.map(d => d.day);
const task = c.task === 'easier_day'
  ? 'The teacher said No twice for Day ' + c.today.day + '. Make an easier version of that day: same level for each group, a different, simpler activity (more hands-on, smaller numbers).'
  : 'Replan the days below after the teacher feedback.' + (c.last_day_of_topic ? ' The reported day was the last day of its topic, so the next topic\'s first days may change.' : '');
const lines = [
  task, '',
  'Feedback:', JSON.stringify(c.feedback, null, 1), '',
  'Diagnosis per group:', JSON.stringify(diagnosis, null, 1), '',
  'Reported day:', JSON.stringify(c.reported_day), '',
  'Days you may change (current plan): ' + allowed.join(', '), JSON.stringify(c.scope_days, null, 1), '',
  'Days after them (context only, do not change):', JSON.stringify(c.next_days), '',
  'Skills (level_id: what the child can do):', JSON.stringify(c.levels, null, 1), '',
  'Activities you may use, per group (activity_id | level_id | title | mode | minutes):',
  ...['A', 'B', 'C'].map(g => 'Group ' + g + ':\n' + c.candidates[g].join('\n')), '',
  'Rules:',
  '- Change only days ' + allowed.join(', ') + '. You may add ONE extra day "<N>a" (for example "' + allowed[allowed.length - 1] + 'a") only if the pending work cannot fit.',
  '- Each day: one level_id and one activity_id per group, taken from the lists above. The activity must belong to that level.',
  '- The three groups are on three different levels each day.',
  '- Pending work goes first: put it in finish_first for that group on the first changed day: one or two full sentences saying what is left from the reported day and the specific numbers or items involved (no IDs). Otherwise finish_first is null.',
  '- A group that said Partly or No stays on the same level with a different activity. A Yes group moves on as planned. A group that is clearly ahead may move up one level.',
  '- Follow the teacher\'s "how to improve" when it fits these rules.',
  '- reason: one short line per day saying what changed and why.',
  '',
  'Reply with JSON only, in this shape:',
  '{"days":[{"day":"' + allowed[0] + '","plan_status":"Updated","insert_after":null,"reason":"...","group_a":{"level_id":"...","activity_id":"...","finish_first":null},"group_b":{"level_id":"...","activity_id":"...","finish_first":"..."},"group_c":{"level_id":"...","activity_id":"...","finish_first":null}}],"pending_placement":"one line"}',
  'For an added day use "plan_status":"Added" and "insert_after":"<N>".',
];
if ($json.errors && $json.errors.length) lines.push('', 'Your last plan broke these rules. Fix every one:', ...$json.errors.map(e => '- ' + e), 'Your last plan:', JSON.stringify($json.plan));
if ($json.revise) lines.push('', 'A reviewer found these problems in your last plan. Fix them:', ...$json.problems.map(x => '- Day ' + x.day + ', Group ' + x.group + ': ' + x.problem + (x.fix_hint ? ' (' + x.fix_hint + ')' : '')), 'Your last plan:', JSON.stringify($json.plan));
return [{ json: { prompt: lines.join('\n'), state: { ...st, plan_calls: st.plan_calls + 1 } } }];

// Step 3: hard rules, checked in code.
const c = $('Gather context').first().json;
const st = $('Plan prompt').last().json.state;
const G = ['A', 'B', 'C'];
const errors = [];
let plan = null;
const parseOut = v => { if (v && typeof v === 'object' && !('text' in v)) return v; let t = String((v && v.text) || '').replace(/<think>[\s\S]*?<\/think>/g, ''); return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
try { plan = parseOut($json); }
catch (e) { errors.push('The reply was not valid JSON. Reply with the JSON object only.'); }
const days = Array.isArray(plan?.days) ? plan.days : [];
if (plan && !days.length) errors.push('"days" is empty.');
const allowed = new Set(c.scope.map(d => String(d.day)));
const anchors = new Set([...allowed, String(c.today.day)]);
let added = 0;
const strandOf = day => { const d = c.day_info[day]; return d && d.groups ? d.groups.A.level_id.slice(0, 3) : null; };
for (const d of days) {
  const day = String(d.day);
  let base = day;
  if (!allowed.has(day)) {
    const m = day.match(/^(\d+)a$/i);
    if (m && anchors.has(m[1]) && String(d.insert_after) === m[1] && !added++) base = m[1];
    else { errors.push('Day ' + day + ': you may not change this day. Allowed: ' + [...allowed].join(', ') + ', plus one added day "<N>a" with insert_after "<N>".'); continue; }
  }
  const strand = strandOf(base) || strandOf(String(c.today.day));
  const lv = [];
  for (const g of G) {
    const x = d['group_' + g.toLowerCase()] || {};
    const a = c.acts[x.activity_id];
    if (!c.level_meta[x.level_id]) errors.push('Day ' + day + ', Group ' + g + ': level_id "' + x.level_id + '" does not exist.');
    if (!a) { errors.push('Day ' + day + ', Group ' + g + ': activity_id "' + x.activity_id + '" does not exist.'); continue; }
    if (a.level_id !== x.level_id) errors.push('Day ' + day + ', Group ' + g + ': ' + x.activity_id + ' is for level ' + a.level_id + ', not ' + x.level_id + '.');
    if (strand && String(x.level_id).slice(0, 3) !== strand) errors.push('Day ' + day + ', Group ' + g + ': level must be in strand ' + strand + '.');
    if (g === 'A' && !/^(oral|hands-on)$/i.test(a.mode)) errors.push('Day ' + day + ', Group A: ' + x.activity_id + ' is ' + a.mode + '. Group A needs oral or hands-on work.');
    if (/^(partly|no)$/i.test(c.result[g] || '') && x.activity_id === c.reported_day['group_' + g.toLowerCase()]?.activity_id) errors.push('Day ' + day + ', Group ' + g + ': ' + x.activity_id + ' is the activity that did not work on Day ' + c.today.day + '. Use a different activity at the same level.');
    if (c.task === 'easier_day' && x.level_id !== c.reported_day['group_' + g.toLowerCase()]?.level_id) errors.push('Day ' + day + ', Group ' + g + ': the easier day keeps the same level (' + c.reported_day['group_' + g.toLowerCase()]?.level_id + ').');
    lv.push(x.level_id);
  }
  if (new Set(lv).size < lv.length) errors.push('Day ' + day + ': the three groups must be on three different levels.');
}
for (const pend of c.feedback.pending) {
  const g = (pend.match(/^Group ([ABC])/) || [])[1];
  const placed = days.some(d => g ? (d['group_' + g.toLowerCase()] || {}).finish_first : G.some(x => (d['group_' + x.toLowerCase()] || {}).finish_first));
  if (!placed) errors.push('Pending work "' + pend + '" is not placed. Put it in finish_first on the first changed day.');
}
const ok = errors.length === 0;
const state = { ...st, fails: st.fails + (ok ? 0 : 1) };
// Inputs for the AgenticOrg challenger, in the shape its prompt expects.
const summary = a => { const s = String(a.steps_english || ''); return s.length > 160 ? s.slice(0, 157) + '...' : s; };
const draft = days.map(d => ({ day: String(d.day), topic: (c.scope.find(s => String(s.day) === String(d.day)) || c.scope[0]).topic,
  plan_status: d.plan_status === 'Added' ? 'Added' : 'Updated', reason: d.reason || '',
  ...Object.fromEntries(G.map(g => { const x = d['group_' + g.toLowerCase()] || {}; const a = c.acts[x.activity_id] || {};
    return ['group_' + g.toLowerCase(), { level_id: x.level_id, activity_id: x.activity_id, activity_title: a.title || '', activity_summary: summary(a), finish_first: x.finish_first || null }]; })) }));
const challenge_inputs = { feedback: c.feedback, diagnosis: $('Read diagnosis').first().json.diagnosis, reported_day: c.reported_day, draft, next_days: c.next_days };
return [{ json: { ok, errors, plan, state, challenge_inputs } }];

// Step 4 result. AgenticOrg may wrap the JSON or put text around it, so look for "verdict" anywhere.
const prev = $('Rule check').last().json;
const find = v => {
  if (typeof v === 'string') { const i = v.indexOf('{'), k = v.lastIndexOf('}'); if (i < 0 || !v.includes('verdict')) return null; try { return find(JSON.parse(v.slice(i, k + 1))); } catch (e) { return null; } }
  if (v && typeof v === 'object') { if (v.verdict) return v; for (const x of Object.values(v)) { const f = find(x); if (f) return f; } }
  return null;
};
const v = find($json);
const problems = v && Array.isArray(v.problems) ? v.problems.slice(0, 6) : [];
const revise = !!v && /^revise$/i.test(String(v.verdict)) && problems.length > 0;
return [{ json: { ...prev, revise, problems, challenge_verdict: v ? String(v.verdict) : 'no answer (' + ($json.error?.message || $json.detail || $json.status || 'unknown') + ')',
  state: { ...prev.state, challenge_round: prev.state.challenge_round + 1 } } }];

// Plan still breaks the rules after 2 retries: keep the old plan, tell Rira.
const ctx = $('Pick days').first().json;
const to = $('Config').first().json.admin_email;
const subject = 'Replanner v2 kept the old plan (Day ' + ctx.today.day + ', ' + ctx.today.topic + ')';
const body = ['The replanner could not make a plan that passes the rules after 3 tries, so the sheet and Docs were not changed.', '',
  'Teacher sheet: ' + ctx.sheet_url, 'Feedback: ' + JSON.stringify(ctx.feedback.sheet || {}), '', 'Last rule errors:', ...($json.errors || []).map(e => '- ' + e), '',
  'Last plan from the model:', JSON.stringify($json.plan)].join('\n');
const raw = ['To: ' + to, 'Subject: =?UTF-8?B?' + Buffer.from(subject).toString('base64') + '?=', 'Content-Type: text/plain; charset=UTF-8', '', body].join('\r\n');
return [{ json: { subject, raw: Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '') } }];

// Step 5 input: the checked plan, with titles and skills. The model writes only the short texts.
const c = $('Gather context').first().json;
const plan = $json.plan;
const G = ['A', 'B', 'C'];
const days = plan.days.map(d => ({ day: String(d.day), reason: d.reason,
  groups: Object.fromEntries(G.map(g => { const x = d['group_' + g.toLowerCase()]; const a = c.acts[x.activity_id];
    return [g, { skill: c.levels[x.level_id] || '', activity: a.title, materials: a.materials, finish_first: x.finish_first || null, said_today: c.result[g] || null }]; })) }));
const prompt = [
  'A maths teacher teaches grades 1-5 in one room in three groups. Write the short texts for her updated day plans.',
  '', 'What she said about Day ' + c.today.day + ':', JSON.stringify(c.feedback, null, 1),
  '', 'New plans:', JSON.stringify(days, null, 1),
  '', 'For each day write:',
  '- opening: a 5-minute whole-class warm-up on the day\'s topic, one or two sentences.',
  '- rotation: one sentence. The teacher works with one group for 15 minutes while the other two practise, then moves on. Start with the group that needs most help.',
  '- for each group: finish_first (only if finish_first is given, else null): ONE string of about 40 to 70 words, with inline labels and inline numbering, built from that group\'s what_went_wrong, how_to_improve and what_is_left. Example: "Left from Day 2: the last 2 dictation rounds. Why: children wrote 408 as 48 when zero sat in the tens place. Do: (1) Say 408, 305, 710; children write them on slates. (2) Ask where the zero goes and why. (3) Show 4 bundles, 0 loose tens, 8 sticks. Time: 10 min. Check: write 506." No line breaks and no lists inside it, check (one concrete check question the teacher can ask; not "Did you understand?"), sheet (a very short line for her plan sheet, max 8 words).',
  'Also write feedback_summary (one plain sentence of what she told us) and changes (one short line per day, like "Day 3: Group B finishes dictation, then works with bundles.").',
  'Simple English. Short sentences. Do not use words that label children, such as weak, slow, struggling, behind, poor, bright or smart. Do not write activity IDs.',
  '', 'Reply with JSON only:',
  '{"feedback_summary":"...","changes":["..."],"days":[{"day":"' + days[0].day + '","opening":"...","rotation":"...","groups":{"A":{"finish_first":null,"check":"...","sheet":"..."},"B":{...},"C":{...}}}]}',
].join('\n');
return [{ json: { prompt, plan } }];

// Step 5 assembly: same layout as the master Docs. Activity steps are copied word for word from the Activities data.
const c = $('Gather context').first().json;
const ctx = $('Pick days').first().json;
const plan = $('Write prompt').last().json.plan;
const G = ['A', 'B', 'C'], NAME = { A: 'A, Beginning', B: 'B, Middle', C: 'C, Advanced' };
let w = {};
const parseOut = v => { if (v && typeof v === 'object' && !('text' in v)) return v; let t = String((v && v.text) || '').replace(/<think>[\s\S]*?<\/think>/g, ''); return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
try { w = parseOut($json); } catch (e) {}
const LABEL = /\b(weak|slow|struggl\w*|behind|poor|bright|smart|dull|lazy|clever)\b/i;
const clean = (v, fallback) => (typeof v === 'string' && v.trim() && !LABEL.test(v) && !/[A-Z]{3}-\d{2}/.test(v)) ? v.trim() : fallback;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// "1. ... 2. ..." -> list items, text unchanged.
const splitSteps = s => {
  const find = (k, from) => { const re = new RegExp('(^|\\s)' + k + '\\.\\s(?=[A-Z0-9"(])', 'g'); re.lastIndex = from; let m, first = null;
    while ((m = re.exec(s))) { const at = m.index + m[1].length; if (first === null) first = at; if (at === 0 || /[.)"!?]\s*$/.test(s.slice(0, at))) return at; } return first; };
  let at = find(1, 0), k = 1; if (at === null) return [s];
  const items = [];
  while (at !== null) { const start = at + String(k).length + 2; const nx = find(k + 1, start); items.push(s.slice(start, nx === null ? s.length : nx).trim()); at = nx; k++; }
  return items;
};
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const d of plan.days) {
  const day = String(d.day), added = d.plan_status === 'Added' || !c.day_info[day];
  const base = added ? (String(d.insert_after || '').match(/\d+/) || [c.scope[0].day])[0] : day;
  const cur = c.day_info[base] || c.day_info[c.scope[0].day];
  const unchanged = !added && cur.groups && G.every(g => { const x = d['group_' + g.toLowerCase()]; return x.activity_id === cur.groups[g].activity_id && !x.finish_first; });
  if (unchanged) continue;
  const wd = (w.days || []).find(x => String(x.day) === day) || {};
  const topic = (c.scope.find(s => String(s.day) === base) || c.scope[0]).topic;
  const strandName = topic.replace(/^T\d+\s*/, '');
  const sheet = {}; const parts = [
