// Existing rows: update in place. One added day: a new row below its anchor.
const ctx = $('Pick days').first().json;
const today = new Date().toISOString().slice(0, 10);
const k = name => ctx.headers.findIndex(x => x.trim().toLowerCase() === name.toLowerCase());
const col = name => { const i = k(name); return i < 0 ? null : String.fromCharCode(65 + i); };
const rowsByNo = new Map(ctx.rows.map(r => [r.row_number, r]));
const docs = $('Build Docs').all();
const data = []; let insert = null;
$input.all().forEach((it, idx) => {
  const d = docs[idx].json;
  const link = '=HYPERLINK("https://docs.google.com/document/d/' + it.json.id + '/edit","Open Day ' + d.day + (d.insert ? ' (added)' : ' (updated)') + '")';
  if (d.insert) {
    const row = new Array(ctx.headers.length).fill('');
    const put = (n, v) => { const i = k(n); if (i >= 0) row[i] = v; };
    put('Day', d.day); put('Topic', d.topic); put('Group A today', d.group_a_today); put('Group B today', d.group_b_today); put('Group C today', d.group_c_today);
    put('Plan', link); put('Plan status', 'Added ' + today);
    insert = { after_row: d.after_row, values: row };
    return;
  }
  const old = rowsByNo.get(d.row_number) || {};
  const set = (n, v) => { const c = col(n); if (c) data.push({ range: "'" + ctx.sheet_title + "'!" + c + d.row_number, values: [[v]] }); };
  set('Group A today', d.group_a_today); set('Group B today', d.group_b_today); set('Group C today', d.group_c_today);
  set('Plan', link); set('Plan status', 'Updated ' + today);
  if (!old.original_cell) set('Original plan', old.plan_cell || '');
});
// The added row goes in after the updates, so earlier row numbers stay valid.
const requests = insert ? [{ insertDimension: { range: { sheetId: ctx.sheet_gid, dimension: 'ROWS', startIndex: insert.after_row, endIndex: insert.after_row + 1 }, inheritFromBefore: true } }] : [];
const insertValues = insert ? [{ range: "'" + ctx.sheet_title + "'!A" + (insert.after_row + 1), values: [insert.values] }] : [];
return [{ json: { body: { valueInputOption: 'USER_ENTERED', data }, requests, insertValues } }];

